<script setup lang="ts">
import type { Programme } from '../../../../packages/contracts/src/programme';
const enhanced=ref(false);onMounted(()=>{enhanced.value=true;});
const props=defineProps<{clips:Programme[]}>();const route=useRoute(),activeByRoute=useState<Record<string,string>>('clip-active-routes',()=>({}));const root=ref<HTMLElement|null>(null),active=ref(Math.max(0,props.clips.findIndex(c=>c.programmeId===activeByRoute.value[route.path]))),playing=ref(false),intent=ref(false),muted=ref(true),captions=ref(true),message=ref(''),sheet=ref(false);const audio=useProgrammeAudio();let observer:IntersectionObserver|undefined;
const reason=computed(()=>(current.value as (Programme & {reason?:{label:string;target:string}})|undefined)?.reason);
const currentTime=ref(0);const fullStory=computed(()=>{const p=current.value;if(!p)return '/';const segment=p.segments.find(s=>s.startMs<=currentTime.value*1000&&s.endMs>currentTime.value*1000)||p.segments[0];const block=segment?.blockIds[0];return {path:`/articles/${p.articleSlugs[0]}`,query:{fromClip:p.programmeId,fromBlock:block},hash:block?`#${block}`:undefined};});
const current=computed(()=>props.clips[active.value]);const video=()=>root.value?.querySelector<HTMLVideoElement>(`video[data-index="${active.value}"]`);
const {data:article}=await useFetch<{data:{id:string;topic:string;slug:string}}>(()=>`/api/v1/articles/${current.value?.articleSlugs[0]}`);
const progressOwner=useState('clip-progress-owner',()=> 'guest');let ownsPlayback=false,alive=true;
const member=useMember(),positions=useState<Record<string,number>>('clip-session-positions',()=>({}));let localResumeAllowed=true,historyEpoch=0;let historyConsent=false,lastWrite=0,writing=false,progressConflict=false;const revisions=new Map<string,number>();
async function persist(p=current.value,v=video()){if(!p||!v)return;if(localResumeAllowed)positions.value[p.renditionKey]=v.currentTime;if(!ownsPlayback||!historyConsent||!member.session.value||writing||progressConflict)return;const epoch=historyEpoch,identity=member.session.value.user.id;writing=true;try{const result=await member.mutate<{data:{revision:number}}>('/api/v1/me/progress','PUT',{programmeId:p.programmeId,renditionKey:p.videoRendition!.renditionKey,positionMs:Math.floor(v.currentTime*1000),revision:revisions.get(p.programmeId)||0});if(alive&&epoch===historyEpoch&&member.session.value?.user.id===identity)revisions.set(p.programmeId,result.data.revision);}catch(e){if(epoch===historyEpoch&&member.session.value?.user.id===identity&&(e as {statusCode?:number}).statusCode===409)progressConflict=true;}finally{writing=false;}}
const captionText=ref('');function time(){if(!alive)return;const track=video()?.textTracks[0];captionText.value=Array.from(track?.activeCues||[]).map(c=>(c as VTTCue).text).join(' ');const p=current.value,v=video();if(p&&v){currentTime.value=v.currentTime;if(localResumeAllowed)positions.value[p.renditionKey]=v.currentTime;if(ownsPlayback&&!audio.playing.value)audio.reportVideo({programme:p,position:v.currentTime,playing:!v.paused,renditionKey:p.videoRendition!.renditionKey});}if(Date.now()-lastWrite>15000){lastWrite=Date.now();void persist();}}
function ownPlayback(){localResumeAllowed=true;ownsPlayback=true;intent.value=true;audio.pause();playing.value=true;audio.setVideoControls({play:()=>void play(),pause,seek:seconds=>{const v=video();if(v)v.currentTime=Math.max(0,Math.min(v.duration,seconds));},nextChapter:move});time();}
function loaded(){if(!alive)return;tracks();const p=current.value,v=video();if(p&&v&&positions.value[p.renditionKey])v.currentTime=Math.min(positions.value[p.renditionKey]!,v.duration||0);}
function clearProgress(){historyEpoch++;localResumeAllowed=false;historyConsent=false;positions.value={};revisions.clear();progressConflict=false;}
onMounted(async()=>{window.addEventListener(`aggregator:clear-history`,clearProgress);await member.refresh();if(!alive)return;const owner=member.session.value?.user.id||`guest`;if(progressOwner.value!==owner){clearProgress();localResumeAllowed=true;progressOwner.value=owner;}if(member.session.value){const epoch=historyEpoch,identity=member.session.value.user.id;try{const consent=(await $fetch<{data:{listeningHistory:boolean}}>('/api/v1/me/preferences')).data.listeningHistory;if(!alive||epoch!==historyEpoch||member.session.value?.user.id!==identity)return;historyConsent=consent;if(historyConsent){const state=(await $fetch<{data:{progress:{programmeId:string;renditionKey:string;positionMs:number;revision:number}[]}}>('/api/v1/me/listening')).data;if(!alive||epoch!==historyEpoch||member.session.value?.user.id!==identity)return;for(const p of state.progress){const c=props.clips.find(c=>c.programmeId===p.programmeId&&c.videoRendition?.renditionKey===p.renditionKey);if(c){positions.value[c.renditionKey]=p.positionMs/1000;revisions.set(p.programmeId,p.revision);}}loaded();}}catch{/* Local playback remains available. */}}});
onBeforeUnmount(()=>{alive=false;void persist();window.removeEventListener('aggregator:clear-history',clearProgress);if(audio.videoState.value?.programme.kind==='clip'){audio.clearVideo();audio.setVideoControls(null);}});
async function copyLink(){try{await navigator.clipboard.writeText(`${location.origin}/clips/${current.value?.programmeId}`);message.value='Clip link copied.';}catch{message.value='Copy the Clip permalink below.';}}
function seekClip(e:Event){const v=video();if(v)v.currentTime=Number((e.target as HTMLInputElement).value);}
function pause(){intent.value=false;video()?.pause();playing.value=false;}
async function play(){const v=video();if(!v)return;audio.pause();for(const other of document.querySelectorAll<HTMLMediaElement>('video,audio'))if(other!==v)other.pause();intent.value=true;message.value='';v.muted=muted.value;try{await v.play();playing.value=true;}catch{playing.value=false;intent.value=false;message.value='Playback was not allowed. Press Play to try again.';}}
function tracks(){const v=video();if(v)for(const t of Array.from(v.textTracks)){t.mode='hidden';for(const cue of Array.from(t.cues||[]))(cue as VTTCue).line=-6;}}
function changed(index:number){if(active.value===index)return;void persist();releaseMedia(video()||null);active.value=index;currentTime.value=0;activeByRoute.value[route.path]=props.clips[index]!.programmeId;playing.value=false;sheet.value=false;nextTick(()=>{tracks();if(intent.value)void play();});}
function move(delta:number){const index=Math.max(0,Math.min(props.clips.length-1,active.value+delta));root.value?.querySelector<HTMLElement>(`[data-clip-index="${index}"]`)?.scrollIntoView({block:'nearest',behavior:'auto'});changed(index);}
function key(e:KeyboardEvent){if(e.target!==root.value)return;if(['ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();const v=video();if(v)v.currentTime=Math.max(0,Math.min(v.duration,v.currentTime+(e.key==='ArrowRight'?5:-5)));return;}if(['PageDown','ArrowDown','PageUp','ArrowUp'].includes(e.key)){e.preventDefault();move(['PageDown','ArrowDown'].includes(e.key)?1:-1);}}
function hidden(){if(document.visibilityState==='hidden')pause();}
function paused(e:Event){const v=e.target as HTMLVideoElement;if(v!==video()||!alive)return;playing.value=false;intent.value=false;void persist(current.value,v);}
function mediaStarted(e:Event){if(e.target!==video()&&e.target instanceof HTMLMediaElement){intent.value=false;video()?.pause();}}
onMounted(()=>{observer=new IntersectionObserver(entries=>{const best=entries.filter(e=>e.intersectionRatio>.6).sort((a,b)=>b.intersectionRatio-a.intersectionRatio)[0];if(best)changed(Number((best.target as HTMLElement).dataset.clipIndex));},{root:root.value,threshold:[.6,.8]});const restored=props.clips.findIndex(c=>c.programmeId===activeByRoute.value[route.path]);if(restored>0)root.value?.querySelector<HTMLElement>(`[data-clip-index="${restored}"]`)?.scrollIntoView({block:'nearest',behavior:'auto'});root.value?.querySelectorAll('[data-clip-index]').forEach(e=>observer?.observe(e));document.addEventListener('visibilitychange',hidden);document.addEventListener('play',mediaStarted,true);});
onBeforeUnmount(()=>{pause();observer?.disconnect();document.removeEventListener('visibilitychange',hidden);document.removeEventListener('play',mediaStarted,true);root.value?.querySelectorAll('video').forEach(v=>releaseMedia(v));});
const dialog=ref<HTMLDialogElement|null>(null),panel=ref('sources'),saved=ref(false),savedLoading=ref(false),saving=ref(false),scrubbing=ref(false),preview=ref(0);let seekStart=0,seekPlaying=false,touchY=0,touchX=0,dragged=false,bookmarkEpoch=0;
watch([()=>article.value?.data.id,()=>member.session.value?.user.id],async()=>{const epoch=++bookmarkEpoch;saved.value=false;savedLoading.value=false;if(!member.session.value||!article.value)return;savedLoading.value=true;try{const r=await $fetch<{data:{articleId:string}[]}>('/api/v1/me/bookmarks');if(epoch===bookmarkEpoch)saved.value=r.data.some(b=>b.articleId===article.value?.data.id);}catch{/* Save remains a retriable explicit operation. */}finally{if(epoch===bookmarkEpoch)savedLoading.value=false;}},{immediate:true});
async function saveItem(){pause();if(!member.session.value){await navigateTo('/sign-in?returnTo='+encodeURIComponent(route.fullPath));return;}if(!member.checked.value||savedLoading.value||saving.value||!article.value||article.value.data.slug!==current.value?.articleSlugs[0])return;const id=article.value.data.id,owner=member.session.value.user.id,epoch=bookmarkEpoch;saving.value=true;try{await member.mutate(`/api/v1/me/bookmarks/${id}`,saved.value?'DELETE':'PUT',{});if(alive&&epoch===bookmarkEpoch&&member.session.value?.user.id===owner){saved.value=!saved.value;message.value=saved.value?'Saved to Library.':'Removed from Library.';}}catch(e){if(epoch===bookmarkEpoch)message.value=memberError(e);}finally{saving.value=false;}}
function openPanel(name:string){pause();panel.value=name;sheet.value=true;dialog.value?.showModal();}
function closePanel(){dialog.value?.close();sheet.value=false;pause();}
async function share(){pause();const url=`${location.origin}/clips/${current.value?.programmeId}`;if(navigator.share){try{await navigator.share({title:current.value?.title,url});message.value='Share sheet completed; delivery is not verified.';}catch(e){message.value=(e as Error).name==='AbortError'?'Sharing cancelled.':'Sharing unavailable; use Copy link in More.';}}else await copyLink();}
function beginSeek(){if(scrubbing.value)return;const v=video();if(!v)return;seekStart=v.currentTime;seekPlaying=!v.paused;preview.value=seekStart;scrubbing.value=true;v.pause();}
function previewSeek(e:Event){beginSeek();preview.value=Number((e.target as HTMLInputElement).value);}
function finishSeek(cancel=false){if(!scrubbing.value)return;const v=video();scrubbing.value=false;if(v)v.currentTime=cancel?seekStart:preview.value;if(seekPlaying)void play();else pause();}
function pictureDown(e:PointerEvent){touchY=e.clientY;touchX=e.clientX;dragged=false;}
function pictureUp(e:PointerEvent){dragged=Math.abs(e.clientY-touchY)>12||Math.abs(e.clientX-touchX)>12;if(!dragged&&!window.getSelection()?.toString())playing.value?pause():void play();}
function speed(e:Event){const v=video();if(v)v.playbackRate=Number((e.target as HTMLSelectElement).value);}
</script>
<template><div class="clip-layout"><div ref="root" class="clip-feed" tabindex="0" aria-label="Clips. Page Down or Next moves to the next highlight." @keydown="key"><article v-for="(clip,i) in clips" :key="clip.renditionKey" class="clip-item" :data-clip-index="i" :aria-label="clip.title"><template v-if="i===active"><video :data-index="i" :src="clip.videoRendition?.url" :poster="clip.videoRendition?.posterUrl" preload="metadata" playsinline :controls="!enhanced" :muted="muted" :aria-label="clip.title" @pointerdown="pictureDown" @pointerup="pictureUp" @play="ownPlayback" @pause="paused" @ended="intent=false;message='End of this Clip. Replay or choose the next highlight.'" @error="message='This video could not play. Retry or read the transcript.'" @loadedmetadata="loaded" @timeupdate="time" @seeked="time" @volumechange="muted=!!video()?.muted"><track kind="captions" srclang="en" label="English" :src="clip.videoRendition?.captionUrl" default @load="tracks"></video><button v-if="!playing&&enhanced" class="clip-center" aria-label="Play" @click="play"><ControlIcon name="play"/></button><div v-if="enhanced" class="clip-edge"><MediaKey :label="playing?'Pause':'Play'" :icon="playing?'pause':'play'" @click="playing?pause():play()"/><MediaKey :label="muted?'Unmute':'Mute'" :icon="muted?'mute':'volume'" @click="muted=!muted;if(video())video()!.muted=muted"/></div></template></article></div>
<template v-if="current"><button v-if="audio.playing.value" class="clip-radio" @click="audio.pause()">Radio playing · Pause</button><aside class="clip-rail" aria-label="Current clip actions"><button :aria-label="saved?'Unsave':'Save'" :aria-pressed="saved" :disabled="!member.checked.value||savedLoading||saving||!article||article.data.slug!==current.articleSlugs[0]" @click="saveItem"><ControlIcon :name="saved?'check':'bookmark'"/><span>{{ saved?'Saved':'Save' }}</span></button><button aria-label="Sources" @click="openPanel('sources')"><ControlIcon name="evidence"/><span>Sources</span></button><button aria-label="Share" @click="share"><ControlIcon name="share"/><span>Share</span></button><button aria-label="More" @click="openPanel('more')"><ControlIcon name="more"/><span>More</span></button></aside><nav class="clip-navigation" aria-label="Clip navigation"><MediaKey label="Previous clip" icon="up" :disabled="active===0" @click="move(-1)"/><span>{{ active+1 }}/{{ clips.length }}</span><MediaKey label="Next clip" icon="down" :disabled="active===clips.length-1" @click="move(1)"/></nav><div class="clip-caption" :aria-hidden="!captions">{{ captions?captionText:'' }}</div><div class="clip-meta"><span>FICTIONAL LOCAL REPORTING</span><NuxtLink :to="fullStory" @click="pause">{{ current.title }} <small>Read story ↗</small></NuxtLink></div><div class="clip-progress"><output v-if="scrubbing||!playing">{{ Math.floor(scrubbing?preview:currentTime) }} / {{ Math.round(current.durationMs/1000) }}s</output><input aria-label="Clip position" type="range" min="0" :max="current.durationMs/1000" step=".1" :value="scrubbing?preview:currentTime" @pointerdown.stop="beginSeek" @input="previewSeek" @change="finishSeek()" @pointercancel="finishSeek(true)" @keydown.esc="finishSeek(true)"></div><p class="clip-status" role="status">{{ message }}</p>
<dialog ref="dialog" class="clip-dialog" @cancel="closePanel" @close="sheet=false;pause()"><header><h2>{{ panel==='sources'?'Sources and transcript':'Clip options' }}</h2><button class="control" @click="closePanel">Close</button></header><template v-if="panel==='sources'"><p>{{ current.syntheticDisclosure }}</p><ol><li v-for="s in current.sources" :key="s.id"><h3>{{ s.title }}</h3><p>{{ s.publisher }}</p><a :href="s.url" rel="noreferrer" target="_blank">Exact original item</a></li></ol><h3>Transcript</h3><p v-for="s in current.segments" :key="s.id">{{ s.text }}</p></template><template v-else><h3>{{ current.title }}</h3><button class="control" :aria-pressed="captions" @click="captions=!captions;tracks()">{{ captions?'Hide captions':'Show captions' }}</button><label>Speed <select aria-label="Clip speed" :value="video()?.playbackRate||1" @change="speed"><option v-for="rate in [.75,1,1.25,1.5,2]" :key="rate" :value="rate">{{ rate }}×</option></select></label><button class="control" @click="copyLink">Copy link</button><button class="control" @click="enhanced=!enhanced">{{ enhanced?'Use native controls':'Use enhanced controls' }}</button><FeedControls v-if="article&&article.data.slug===current.articleSlugs[0]" :article-id="article.data.id" :topic="reason?.target"/><p v-if="reason">Because you follow {{ reason.label }}</p><NuxtLink :to="`/clips/${current.programmeId}#sources`">Public transcript and complete sources</NuxtLink></template></dialog></template></div></template>
<style scoped>
